#include "luca/pbmp.h"
#include <assert.h>
#include <string.h>
int main(void){struct luca_command_queue q;assert(luca_command_queue_init(&q)==0);struct luca_pbmp_state s={"LuCa","irc.example","#luca",1,2,&q};char b[2048];assert(luca_pbmp_response("{\"pbmp\":1,\"type\":\"request\",\"id\":\"42\",\"method\":\"bot.info\",\"params\":{}}",&s,b,sizeof b)==0);assert(strstr(b,"\"id\":\"42\""));assert(strstr(b,"\"implementation\":\"luca\""));assert(strstr(b,"\"state\":\"online\""));assert(luca_pbmp_response("{\"pbmp\":1,\"type\":\"request\",\"id\":\"9\",\"method\":\"x\",\"params\":{}}",&s,b,sizeof b)==0);assert(strstr(b,"not_supported"));assert(luca_pbmp_response("{\"pbmp\":1,\"type\":\"request\",\"id\":\"3\",\"method\":\"channels.list\",\"params\":{}}",&s,b,sizeof b)==0);assert(strstr(b,"\"name\":\"#luca\""));assert(luca_pbmp_response("{\"pbmp\":1,\"type\":\"request\",\"id\":\"4\",\"method\":\"capabilities.list\",\"params\":{}}",&s,b,sizeof b)==0);assert(strstr(b,"channels.list")&&strstr(b,"channels.join")&&strstr(b,"channels.part"));assert(luca_pbmp_response("{\"pbmp\":1,\"type\":\"request\",\"id\":\"5\",\"method\":\"channels.join\",\"params\":{\"network\":\"irc.example\",\"name\":\"#new\"}}",&s,b,sizeof b)==0);char line[512];assert(luca_command_dequeue(&q,line,sizeof line)==0);assert(strcmp(line,"JOIN #new")==0);luca_command_queue_destroy(&q);return 0;}
